268	    private static void setContextClassLoader(final Thread t, final ClassLoader cl) {
269	        AccessController.doPrivileged(new PrivilegedAction<Void>() {
270	            @Override
271	            public Void run() {
272	                t.setContextClassLoader(cl);
273	                return null;
274	            }
275	        });
276	    }
